diff --git a/infra/dumps.tf b/infra/dumps.tf
new file mode 100644
index 0000000..53cc552
--- /dev/null
+++ b/infra/dumps.tf
@@ -0,0 +1,74 @@
+# DATA-90 – nightly database dump bucket, retained for 35 days
+
+resource "aws_s3_bucket" "db_dumps" {
+  bucket = "shop-db-dumps-${var.env}"
+
+  tags = {
+    Name        = "shop-db-dumps-${var.env}"
+    Environment = var.env
+    ManagedBy   = "terraform"
+  }
+}
+
+# Block all public access – dumps contain sensitive data
+resource "aws_s3_bucket_public_access_block" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  block_public_acls       = true
+  block_public_policy     = true
+  ignore_public_acls      = true
+  restrict_public_buckets = true
+}
+
+# Enforce bucket-owner-enforced ownership (disables ACLs; safest default)
+resource "aws_s3_bucket_ownership_controls" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  rule {
+    object_ownership = "BucketOwnerEnforced"
+  }
+}
+
+# Encrypt dumps at rest with SSE-S3 (no extra cost, no key management)
+resource "aws_s3_bucket_server_side_encryption_configuration" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  rule {
+    apply_server_side_encryption_by_default {
+      sse_algorithm = "AES256"
+    }
+    bucket_key_enabled = true
+  }
+}
+
+# Enable versioning so an accidental overwrite can be recovered
+resource "aws_s3_bucket_versioning" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  versioning_configuration {
+    status = "Enabled"
+  }
+}
+
+# Expire current objects after 35 days; clean up non-current versions after 7 days
+resource "aws_s3_bucket_lifecycle_configuration" "db_dumps" {
+  # Lifecycle depends on versioning being active first
+  depends_on = [aws_s3_bucket_versioning.db_dumps]
+
+  bucket = aws_s3_bucket.db_dumps.id
+
+  rule {
+    id     = "expire-dumps-35-days"
+    status = "Enabled"
+
+    filter {} # applies to all objects in the bucket
+
+    expiration {
+      days = 35
+    }
+
+    noncurrent_version_expiration {
+      noncurrent_days = 7
+    }
+  }
+}

