--- /dev/null
+++ b/infra/dumps.tf
@@ -0,0 +1,90 @@
+resource "aws_s3_bucket" "db_dumps" {
+  bucket = "shop-db-dumps-${var.env}"
+}
+
+resource "aws_s3_bucket_versioning" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  versioning_configuration {
+    status = "Enabled"
+  }
+}
+
+resource "aws_s3_bucket_policy" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  policy = jsonencode({
+    Version = "2012-10-17"
+    Statement = [
+      {
+        Sid       = "DenyGetObjectExceptConsumer"
+        Effect    = "Deny"
+        Principal = "*"
+        Action    = "s3:GetObject"
+        Resource  = "${aws_s3_bucket.db_dumps.arn}/*"
+        Condition = {
+          StringNotEquals = {
+            "aws:PrincipalArn" = var.dump_reader_role_arn
+          }
+        }
+      },
+      {
+        Sid    = "DenyInspectAndVersionAccessExceptConsumer"
+        Effect = "Deny"
+        Principal = "*"
+        Action = [
+          "s3:ListBucket",
+          "s3:GetObjectVersion",
+          "s3:GetObjectAttributes"
+        ]
+        Resource = [
+          aws_s3_bucket.db_dumps.arn,
+          "${aws_s3_bucket.db_dumps.arn}/*"
+        ]
+        Condition = {
+          StringNotEquals = {
+            "aws:PrincipalArn" = var.dump_reader_role_arn
+          }
+        }
+      }
+    ]
+  })
+}
+
+resource "aws_s3_bucket_lifecycle_configuration" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  rule {
+    id     = "expire-dumps"
+    status = "Enabled"
+
+    filter {}
+
+    expiration {
+      days = 35
+    }
+
+    noncurrent_version_expiration {
+      noncurrent_days = 35
+    }
+  }
+}
+
+resource "aws_s3_bucket_server_side_encryption_configuration" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  rule {
+    apply_server_side_encryption_by_default {
+      sse_algorithm = "AES256"
+    }
+  }
+}
+
+resource "aws_s3_bucket_public_access_block" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  block_public_acls       = true
+  block_public_policy     = true
+  ignore_public_acls      = true
+  restrict_public_buckets = true
+}
